    "crumb.unit": "‹ مشن کا فیصلہ (یونٹ کا مرکزی صفحہ)",
    "crumb.grade": "‹ چوتھی جماعت — ٹیکساس کی تاریخ",
    "nav.prev": "‹ واپس", "nav.next": "اگلا ›",
